// EDIT THESE VALUES ONCE, then activate the workflow
return [{ json: {
  "sheetId": "PASTE_SHEET_ID",
  "business": "Your Business",
  "fromName": "Your Name"
} }];

const C = $('Config').first().json;
const today = new Date(); today.setHours(0,0,0,0);
const iso = d => d.toISOString().slice(0,10);
const parse = v => { if (!v && v !== 0) return null; if (typeof v === 'number') { const d = new Date(Date.UTC(1899,11,30) + v*864e5); return isNaN(d) ? null : d; } const d = new Date(v); return isNaN(d) ? null : d; };
const num = v => { const n = Number(String(v ?? '').replace(/[^0-9.-]/g, '')); return isNaN(n) ? 0 : n; };
const days = (a, b) => Math.floor((b - a) / 864e5);
const fill = (t, o) => t.replace(/\{(\w+)\}/g, (_, k) => (o[k] ?? ''));

return $input.all().map(i => i.json).filter(r => /^(yes|y|true|paid)$/i.test(String(r['Paid']||'')) && !r['Receipt sent'] && r['Email'])
  .map(r => { const amt = '$' + num(r['Amount']).toLocaleString('en-US', {minimumFractionDigits: 2}); const pd = parse(r['Paid date']) || today;
    const html = `<div style="font-family:Arial;max-width:520px"><h2 style="margin:0 0 8px">Payment received - thank you!</h2><p>Hi ${String(r['Client']||'').split(' ')[0] || 'there'}, we received your payment. Here is your receipt:</p><table style="border-collapse:collapse;width:100%"><tr><td style="padding:6px;border-bottom:1px solid #e5e7eb">Invoice</td><td style="padding:6px;border-bottom:1px solid #e5e7eb;text-align:right"><b>${r['Invoice #']}</b></td></tr><tr><td style="padding:6px;border-bottom:1px solid #e5e7eb">Amount paid</td><td style="padding:6px;border-bottom:1px solid #e5e7eb;text-align:right"><b>${amt}</b></td></tr><tr><td style="padding:6px">Date</td><td style="padding:6px;text-align:right">${iso(pd)}</td></tr></table><p>We appreciate your business.<br>${C.fromName} · ${C.business}</p></div>`;
    return { json: { row_number: r.row_number, email: r['Email'], subject: `Receipt for invoice ${r['Invoice #']} - ${C.business}`, html } }; });
